# NickFlix 4.11 avatar pack: ~110 more original flat-design avatars (ids continue after the 4.7 set).
# Existing ids 0-126 are never changed, so every profile keeps its avatar. Art is drawn here as SVG and
# rendered to 240px PNGs with headless Chrome:  python3 tools/mkav3.py app
import json, os, re, sys, math
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mkav2 import svg, pal, hx
APP = sys.argv[1] if len(sys.argv) > 1 else 'app'
FIRST = 127
W = '#ffffff'; K = '#1b1b24'
def eye(x, y, r=9): return '<circle cx="%d" cy="%d" r="%d" fill="#fff"/><circle cx="%d" cy="%d" r="%d" fill="%s"/>' % (x, y, r, x + 1, y + 1, max(3, r // 2), K)
def eyes2(y=110, dx=26, r=9, cx=120): return eye(cx - dx, y, r) + eye(cx + dx, y, r)
def dot(x, y, r, c): return '<circle cx="%d" cy="%d" r="%d" fill="%s"/>' % (x, y, r, c)
def smile(cx=120, y=140, w=22, c=K, sw=6): return '<path d="M%d %d q%d %d %d 0" stroke="%s" stroke-width="%d" fill="none" stroke-linecap="round"/>' % (cx - w, y, w, w * 0.8, 2 * w, c, sw)
def star(cx, cy, r, c, ri=None):
    ri = ri or r * 0.45; pts = []
    for i in range(10):
        a = -math.pi / 2 + i * math.pi / 5; rr = r if i % 2 == 0 else ri
        pts.append('%.1f,%.1f' % (cx + rr * math.cos(a), cy + rr * math.sin(a)))
    return '<polygon points="%s" fill="%s"/>' % (' '.join(pts), c)

