# ---------- Patterns & colours ----------
def pat(kind, c):
    if kind == 'Stripes': return ''.join('<path d="M%d -20 l-140 280" stroke="%s" stroke-width="18"/>' % (x, c) for x in range(0, 420, 44))
    if kind == 'Polka dots': return ''.join(dot(x + (22 if (y // 44) % 2 else 0), y, 12, c) for x in range(0, 260, 44) for y in range(0, 260, 44))
    if kind == 'Checkers': return ''.join('<rect x="%d" y="%d" width="40" height="40" fill="%s"/>' % (x, y, c) for x in range(0, 240, 40) for y in range(0, 240, 40) if (x // 40 + y // 40) % 2 == 0)
    if kind == 'Zigzag': return ''.join('<path d="M0 %d %s" stroke="%s" stroke-width="12" fill="none"/>' % (y, ' '.join('l20 -20 l20 20' for _ in range(7)), c) for y in range(40, 260, 50))
    if kind == 'Waves': return ''.join('<path d="M-20 %d q30 -24 60 0 t60 0 t60 0 t60 0 t60 0" stroke="%s" stroke-width="12" fill="none"/>' % (y, c) for y in range(30, 260, 44))
    if kind == 'Triangles': return ''.join('<path d="M%d %d l24 40 h-48z" fill="%s" opacity="%.2f"/>' % (x + (24 if (y // 44) % 2 else 0), y, c, .5 + ((x + y) % 3) * .25) for x in range(0, 260, 48) for y in range(0, 260, 44))
    if kind == 'Hexagons':
        out = ''
        for i, y in enumerate(range(0, 260, 52)):
            for x in range(0, 260, 60):
                cx = x + (30 if i % 2 else 0); pts = ' '.join('%.0f,%.0f' % (cx + 26 * math.cos(a * 1.047), y + 26 * math.sin(a * 1.047)) for a in range(6))
                out += '<polygon points="%s" fill="none" stroke="%s" stroke-width="6"/>' % (pts, c)
        return out
    if kind == 'Confetti':
        import random; r = random.Random(7); cols = ['#ffeb3b', '#ff4081', '#40c4ff', '#69f0ae', '#ffffff']
        return ''.join('<rect x="%d" y="%d" width="16" height="7" rx="3" fill="%s" transform="rotate(%d %d %d)"/>' % (x, y, r.choice(cols), a, x, y) for x, y, a in [(r.randint(0, 230), r.randint(0, 230), r.randint(0, 180)) for _ in range(40)])
    if kind == 'Sunburst': return ''.join('<path d="M120 120 L%.0f %.0f L%.0f %.0f z" fill="%s"/>' % (120 + 200 * math.cos(a), 120 + 200 * math.sin(a), 120 + 200 * math.cos(a + .26), 120 + 200 * math.sin(a + .26), c) for a in [i * .524 for i in range(12)])
    if kind == 'Spiral': return '<path d="%s" stroke="%s" stroke-width="12" fill="none" stroke-linecap="round"/>' % ('M120 120 ' + ' '.join('L%.0f %.0f' % (120 + t * 3.2 * math.cos(t / 4), 120 + t * 3.2 * math.sin(t / 4)) for t in range(1, 34)), c)
    if kind == 'Diamonds': return ''.join('<path d="M%d %d l20 -30 l20 30 l-20 30z" fill="%s"/>' % (x + (20 if (y // 60) % 2 else 0), y, c) for x in range(-20, 260, 40) for y in range(30, 280, 60))
    if kind == 'Plaid': return ''.join('<rect x="%d" y="0" width="22" height="240" fill="%s" opacity=".45"/><rect x="0" y="%d" width="240" height="22" fill="%s" opacity=".45"/>' % (v, c, v, c) for v in range(10, 240, 60)) + ''.join('<path d="M%d 0 v240 M0 %d h240" stroke="%s" stroke-width="3" opacity=".7"/>' % (v + 40, v + 40, c) for v in range(10, 240, 60))
    if kind == 'Rings': return ''.join('<circle cx="120" cy="120" r="%d" stroke="%s" stroke-width="10" fill="none"/>' % (r, c) for r in range(16, 180, 28))
    if kind == 'Starfield': return ''.join(star(x, y, s, c) for x, y, s in ((40, 50, 14), (180, 40, 10), (120, 110, 26), (60, 180, 12), (200, 170, 16), (100, 30, 6), (210, 100, 6), (30, 120, 7), (150, 210, 8)))
    if kind == 'Pixel heart': return ''.join('<rect x="%d" y="%d" width="20" height="20" fill="%s"/>' % (40 + 20 * x, 50 + 20 * y, c) for y, row in enumerate(['01100110', '11111111', '11111111', '11111111', '01111110', '00111100', '00011000']) for x, ch in enumerate(row) if ch == '1')
    if kind == 'Lightning bolts': return ''.join('<path d="M%d %d l-16 30 h14 l-8 26 l26 -36 h-14 l10 -20z" fill="%s"/>' % (x, y, c) for x, y in ((60, 30), (150, 50), (100, 120), (200, 140), (40, 160), (170, 190)))
PATTERNS = [('Stripes', 0), ('Polka dots', 330), ('Checkers', 210), ('Zigzag', 45), ('Waves', 190), ('Triangles', 280), ('Hexagons', 160), ('Confetti', 260), ('Sunburst', 20),
            ('Spiral', 300), ('Diamonds', 120), ('Plaid', 0), ('Rings', 230), ('Starfield', 250), ('Pixel heart', 340), ('Lightning bolts', 60)]
A['Patterns & colours'] = [(nm, h, None) for nm, h in PATTERNS]

ORDER = ['Wild animals', 'Ocean', 'Birds & bugs', 'Dinosaurs', 'Vehicles', 'More sports', 'Music & games', 'Nature & weather', 'Fun characters', 'Patterns & colours']
# where the new categories sit in the picker (after an existing category, or at the end)
AFTER = {'Wild animals': 'Animals', 'Ocean': 'Wild animals', 'Birds & bugs': 'Ocean', 'Dinosaurs': 'Birds & bugs', 'More sports': 'Sports', 'Nature & weather': 'Yukon & outdoors', 'Fun characters': 'Characters & monsters'}

def build():
    os.makedirs('dist/avsrc3', exist_ok=True)
    src = open(os.path.join(APP, 'js/avatars.js')).read()
    cats = json.loads(re.search(r'var AV_CATS = (\[.*?\]);', src).group(1))
    names = json.loads(re.search(r'var AV_NAMES = (\{.*?\});', src).group(1))
    # idempotent: drop anything this script added before
    cats = [c for c in cats if c['t'] not in ORDER]
    names = {k: v for k, v in names.items() if int(k) < FIRST}
    n = FIRST; items = []
    for cat in ORDER:
        ids = []
        for nm, h, body in A[cat]:
            if body is None:   # pattern: bold colour background + tone-on-tone motif
                c1, c2 = pal(h); body = pat(nm, hx((h + 180) % 360, .9, .7) if nm in ('Confetti',) else '#ffffff'); body = '<g opacity=".55">' + body + '</g>'
            else:
                c1, c2 = pal(h)
            items.append((n, svg(c1, c2, body, n), nm)); names[str(n)] = nm; ids.append(n); n += 1
        entry = {'t': cat, 'ids': ids}
        at = AFTER.get(cat); pos = next((i for i, c in enumerate(cats) if c['t'] == at), None)
        if pos is None: cats.append(entry)
        else: cats.insert(pos + 1, entry)
    for num, s, nm in items: open('dist/avsrc3/%d.svg' % num, 'w').write(s)
    return items, cats, names, n

def render(items, cats, names, count):
    from playwright.sync_api import sync_playwright
    with sync_playwright() as p:
        b = p.chromium.launch(executable_path=os.environ.get('CHROME', '/usr/bin/google-chrome')); pg = b.new_page(viewport={'width': 240, 'height': 240})
        for num, s, nm in items:
            pg.set_content('<html><body style="margin:0;background:transparent">' + s + '</body></html>')
            pg.locator('svg').screenshot(path=os.path.join(APP, 'img/av/%d.png' % num), omit_background=True)
        b.close()
    js = '/* generated by mkav2.py + mkav3.py (4.11) */\nvar AV_CATS = ' + json.dumps(cats) + ';\nvar AV_NAMES = ' + json.dumps(names) + ';\nAVATARS = ' + str(count) + ';\n'
    open(os.path.join(APP, 'js/avatars.js'), 'w').write(js)
    print('avatars total', count, 'new', len(items), [(c['t'], len(c['ids'])) for c in cats])

if __name__ == '__main__':
    render(*build())
